__NUXT_JSONP__("/ru/price-v2", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{details:{slug:c,pageTitle:"Цены | Mentor Language Institute",pageDescription:"Если у вас есть собственное жилье, вам не нужно платить ② Сбор за проживание",title:"Цены",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fru\u002Fprice-auto\"\u003EКалькулятор цены\u003C\u002Fa\u003E"]}]},steps:{title:"①Оплата за обучение＋② Сбор за проживание＋③Другие сборы",subtitle:["Если у вас есть собственное жилье, вам не нужно платить ② Сбор за проживание\u003Cbr\u003E*Пожалуйста воспользуйтесь  \u003Ca href=\"\u002Fru\u002Fprice-auto\u002F\"\u003EКалькулятор цены\u003C\u002Fa\u003E  для получения расчета."],lists:[{title:"①Оплата за обучение",subtitle:["Цена меняется в зависимости от вашего курса и продолжительности вашего пребывания. Чем дольше вы учитесь в MLI, тем больше скидка."],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",link:["\u003Cb\u003EB&O\u003C\u002Fb\u003E","\u003Cb\u003EB:\u003C\u002Fb\u003E Могу ли я изменить курс после начала обучения? \u003Cbr \u002F\u003E\u003Cb\u003EO:\u003C\u002Fb\u003E Да, вы можете!","\u003Cbr \u002F\u003E"],category:[{title:"Дополнительные услуги",table:{tableMaxCol:d,title_optional:"Изменение статуса (если у вас есть виза B1\u002FB2 или J1 и вы в настоящее время находитесь в США) или восстановление",tbody:[["\u003Cb\u003EОписание денежных сборов\u003C\u002Fb\u003E","\u003Cb\u003EВиды заявителей\u003C\u002Fb\u003E","\u003Cb\u003EСборы\u003C\u002Fb\u003E","\u003Cb\u003EЧисло заявителей\u003C\u002Fb\u003E"],["Плата за обслуживание составляет 1885 долларов США, включая плату за заполнение (370 долларов США) и почтовый сбор. \u003Cbr\u003E *После одобрения студенту будет использовано 600 долларов США в качестве кредита на обучение (безналичная стоимость).","Студенческая виза F1","$1,885","1"],["Плата за обслуживание в размере 365 долларов США за каждого иждивенца","Виза подопечного F2","$365",b]]}}]},{title:"② Сбор за проживание",subtitle:["Мы предоставляем студентам проживание в принимающей семье и общежитии. Проживание в семье рекомендуется для людей, которые хотели бы окунуться в американскую культуру. Общежития рекомендуется для людей, которые хотели бы завести новых друзей."],category:[{title:"Цены на проживание в принимающей семье",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003EЕсли вам меньше 18 лет, арендная плата будет примерно на 10% выше, чем цена для студента старше 18 лет.",thead:[b,e,"Shared***"],tbody:[[f,a,a],[g,"$436","$384"],[h,"$872","$768"],[i,"$1,308","$1,152"],[j,"$1,744","$1,536"],[k,"$3,160","$2,904"],[l,"$4,740","$4,356"]]}},{title:"Цены на проживание в общежитие",table:{tableMaxCol:d,title:"Placement Fee* : $200\u003Cbr \u002F\u003EЕсли вам меньше 18 лет, арендная плата будет примерно на 10% выше, чем цена для студента старше 18 лет.",thead:[b,e,"Shared (2 people)","Quad (4 people)"],tbody:[[f,a,a,a],[g,"$550","$410",a],[h,"$1,100","$820","$600"],[i,"$1,650","$1,230","$900"],[j,"$2,200","$1,640","$1,200"],[k,"$4,160","$2,960","$2,160"],[l,"$6,240","$4,440","$3,240"]]},description:["*Сбор за размещение взимается один раз. Невозвратный.\u003Cbr \u002F\u003E**Депозит за проживание будет возвращен после того как студет освободит комнату.\u003Cbr \u002F\u003E***Если вы хотите проживать в комнате на двоих  \u003Cspan class=\"rmarker\"\u003Eвы должы самостоятельно выбрать себе соседа.\u003C\u002Fspan\u003E","※Ваше размещение будет предоставлено Службой поддержки США или другими агентами.","\u003Ca href=\"\u002Fru\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E   Больше информации о проживание\u003C\u002Fa\u003E"]}]},{title:"③ Первоначальные взносы",subtitle:["В дополнение к вышеуказанным сборам, есть и другие первоначальные взносы."],lists:["Первоначальный сбор школы： $150","Пересылка I-20 по почте** :$120","SEVIS fee**： $350(Уплачивается прямо SEVP)","Книги： $150-240"],description:["*Не возвратные\u003Cbr \u002F\u003E**Если заявка на студенческую визу была уже подана"]}]},examples:{title:"Примеры",subtitle:["«Вот примеры платежей: 4 недели и 48 недель"],lists:[{title:"1 месяц(4 недели)",items:[m,"Оплата за обучение: $1,220","Проживание: $1,560（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003EВсего : $2,930\u003C\u002Fspan\u003E"]},{title:"1 год(48 недель)",items:[m,"Оплата за обучение: $10,032","Проживание: $12,360（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003EВсего : $22,542\u003C\u002Fspan\u003E"]}]},other_info:["Если у вас возникнут вопросы по поводу сборов, пожалуйста, свяжитесь с нами."],dir:"\u002Fprice-v2",path:"\u002Fprice-v2\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:30.524Z",updatedAt:"2026-03-24T13:34:16.697Z"},lang:c}],fetch:{},mutations:void 0}}("$300","","ru",4,"Private (Individual)","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks","Первоначальный сбор: $150")));